//! The page's utility stylesheet, `utilities.css`, generated by encre-css
//! from the class lists in the components and committed beside
//! `index.html`, which Trunk copies as plain CSS. The tests here keep it
//! current; `UPDATE_EXPECT=1` rewrites it:
//!
//! ```text
//! UPDATE_EXPECT=1 cargo nextest run --manifest-path crates/site/Cargo.toml \
//!   --config-file .config/nextest.toml -E 'test(the_committed_stylesheet_is_current)'
//! ```

use std::path::{Path, PathBuf};

use encre_css::{Config, Preflight};

/// The rust/ink palette shared with playwright-rust.dev, as `text-rust-300`,
/// `bg-ink-900`, and the rest, and as `--color-rust-300` for `site.css`.
const PALETTE: [(&str, &str); 8] = [
    ("rust-50", "#fdf3ef"),
    ("rust-100", "#fbe2d7"),
    ("rust-300", "#f0a884"),
    ("rust-500", "#ce422b"),
    ("rust-600", "#b5391f"),
    ("rust-700", "#8f2d19"),
    ("ink-900", "#1a1410"),
    ("ink-800", "#241c16"),
];

const HEADER: &str =
    "/* Generated by encre-css from the class lists in src/ (src/style.rs); never edit by hand.
   Preflight, the palette's variables, and the utilities sit in the base
   and utilities layers, as Tailwind's do, so the page's and the
   architecture tree's unlayered rules win over them. */
";

/// The `link` types Trunk runs a tool for or copies as a stylesheet.
const STYLESHEET_RELS: [&str; 5] = ["css", "sass", "scss", "tailwind-css", "tailwind-css-extra"];

/// The stylesheets `index.html` links: the generated one, the wordmark's,
/// and the page's own.
const LINKED_STYLESHEETS: [&str; 3] = ["utilities.css", "../../brand/wordmark.css", "site.css"];

fn config(preflight: Preflight) -> Config {
    let mut config = Config::default();
    config.preflight = preflight;
    for (name, value) in PALETTE {
        config.theme.colors.add(name, value);
    }
    config
}

fn site_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// Every `.rs` file under `dir`, in path order.
fn rust_files(dir: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    let mut entries: Vec<PathBuf> = std::fs::read_dir(dir)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .collect();
    entries.sort();
    for path in entries {
        if path.is_dir() {
            files.extend(rust_files(&path));
        } else if path.extension().is_some_and(|ext| ext == "rs") {
            files.push(path);
        }
    }
    files
}

/// `source` up to its inline test module (`#[cfg(test)] mod tests {`),
/// when it has one: class lists live in the code the page runs. A
/// `#[cfg(test)]` on a helper, a declared module, or in a string is not a
/// cut.
fn without_tests(source: &str) -> &str {
    let marker = "#[cfg(test)]";
    let mut from = 0;
    while let Some(at) = source[from..].find(marker).map(|at| from + at) {
        let after = at + marker.len();
        if let Some(decl) = source[after..].trim_start().strip_prefix("mod ")
            && decl
                .find(['{', ';'])
                .is_some_and(|c| decl.as_bytes()[c] == b'{')
        {
            return &source[..at];
        }
        from = after;
    }
    source
}

/// The string literals in `source`, each with the text before it, read by
/// a lexer that knows just enough Rust: `//` comments, char literals
/// (`'"'` among them), and raw strings, so a quote in any of those does
/// not swallow the class lists after it.
fn literals(source: &str) -> Vec<(&str, &str)> {
    let bytes = source.as_bytes();
    let is_ident = |c: char| c.is_ascii_alphanumeric() || c == '_';
    let mut found = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'/' if bytes.get(i + 1) == Some(&b'/') => {
                i = source[i..].find('\n').map_or(bytes.len(), |at| i + at);
            }
            b'\'' => {
                // `'x'` or `'\n'` is a char literal; `'a` is a lifetime.
                i += match (bytes.get(i + 1), bytes.get(i + 2)) {
                    (Some(b'\\'), _) => source[i + 2..].find('\'').map_or(1, |at| at + 3),
                    (Some(_), Some(b'\'')) => 3,
                    _ => 1,
                };
            }
            b'"' => {
                let before = &source[..i];
                let hashes = before.len() - before.trim_end_matches('#').len();
                let prefix = &before[..before.len() - hashes];
                let is_raw = prefix
                    .strip_suffix('r')
                    .map(|p| p.strip_suffix('b').unwrap_or(p))
                    .is_some_and(|p| !p.ends_with(is_ident));
                let body = i + 1;
                let close = if is_raw {
                    let terminator = format!("\"{}", "#".repeat(hashes));
                    source[body..].find(&terminator).map(|at| body + at)
                } else {
                    let mut escaped = false;
                    source[body..].char_indices().find_map(|(at, c)| {
                        let closes = c == '"' && !escaped;
                        escaped = c == '\\' && !escaped;
                        closes.then_some(body + at)
                    })
                };
                let Some(close) = close else { break };
                found.push((before, &source[body..close]));
                i = close + 1 + hashes;
            }
            _ => i += 1,
        }
    }
    found
}

/// Whether a literal after `before` is a `class` attribute's value.
fn in_class_attribute(before: &str) -> bool {
    let before = before.trim_end();
    before.ends_with("class=")
        || before
            .trim_end_matches('(')
            .trim_end()
            .ends_with("class=format!")
}

/// Whether `word` is shaped like a utility class: lowercase letters,
/// digits, and hyphens, with punctuation only where the names put it: a
/// `:` before a variant's letters (`hover:text-rust-500`), a `.` between
/// digits (`py-0.5`), a `/` before an opacity (`bg-rust-500/10`), and
/// anything but a space inside `[...]` (`w-[min(32rem,calc(100vw-2rem))]`).
/// Prose fails on its first comma, colon, or dot.
fn is_utility_shaped(word: &str) -> bool {
    let bytes = word.as_bytes();
    if !word.starts_with(|c: char| c.is_ascii_lowercase() || c == '-') {
        return false;
    }
    let mut depth = 0usize;
    for (i, &b) in bytes.iter().enumerate() {
        let prev = i.checked_sub(1).map(|p| bytes[p]);
        let next = bytes.get(i + 1).copied();
        let ok = match b {
            b'[' => {
                depth += 1;
                true
            }
            b']' if depth > 0 => {
                depth -= 1;
                true
            }
            _ if depth > 0 => true,
            b'a'..=b'z' | b'0'..=b'9' | b'-' => true,
            b':' => next.is_some_and(|n| n.is_ascii_lowercase() || n == b'-'),
            b'.' => {
                prev.is_some_and(|p| p.is_ascii_digit()) && next.is_some_and(|n| n.is_ascii_digit())
            }
            b'/' => next.is_some_and(|n| n.is_ascii_digit()),
            _ => false,
        };
        if !ok {
            return false;
        }
    }
    depth == 0
}

/// The words of a class list, less `format!` placeholders.
fn words(list: &str) -> Vec<&str> {
    list.split_whitespace()
        .filter(|word| !word.contains(['{', '}']))
        .collect()
}

/// Whether encre-css writes a rule for the single class `class`.
fn has_rule(class: &str) -> bool {
    !encre_css::generate([class], &config(Preflight::new_none()))
        .trim()
        .is_empty()
}

/// The class lists in `source`: every `class` attribute's value, and any
/// other literal shaped like one (each word a utility class name, at least
/// one of them known to encre-css), which is how a list built in a `let`,
/// a `const`, a prop default, or a `match` arm is told from prose. The
/// generator and the check both read these, so they agree on what a class
/// is.
fn class_lists(source: &str) -> Vec<String> {
    literals(without_tests(source))
        .into_iter()
        .filter(|(before, literal)| {
            let words = words(literal);
            !words.is_empty()
                && (in_class_attribute(before)
                    || (words.iter().all(|word| is_utility_shaped(word))
                        && words.iter().any(|word| has_rule(word))))
        })
        .map(|(_, literal)| literal.to_string())
        .collect()
}

/// The class lists of every component.
fn site_class_lists() -> Vec<String> {
    rust_files(&site_dir().join("src"))
        .iter()
        .flat_map(|path| class_lists(&std::fs::read_to_string(path).unwrap()))
        .collect()
}

/// `utilities.css` for these class lists.
fn stylesheet(class_lists: &[String]) -> String {
    let preflight = encre_css::generate(std::iter::empty::<&str>(), &config(Preflight::new_full()));
    let palette: String = PALETTE
        .iter()
        .map(|(name, value)| format!("  --color-{name}: {value};\n"))
        .collect();
    let utilities = encre_css::generate(
        class_lists.iter().map(String::as_str),
        &config(Preflight::new_none()),
    );
    format!(
        "{HEADER}\n@layer base {{\n{}\n\n:root {{\n{palette}}}\n}}\n\n@layer utilities {{\n{}\n}}\n",
        preflight.trim_end(),
        utilities.trim_end()
    )
}

/// `css` with its comments removed.
fn without_comments(css: &str) -> String {
    let mut out = String::new();
    let mut rest = css;
    while let Some(open) = rest.find("/*") {
        out.push_str(&rest[..open]);
        rest = rest[open..]
            .find("*/")
            .map_or("", |close| &rest[open + close + 2..]);
    }
    out.push_str(rest);
    out
}

/// The classes the page's own stylesheet and the wordmark's define: each
/// `.name` in a selector, never in a declaration, where `0.45` and
/// `.woff2` are not classes.
fn hand_written_classes() -> Vec<String> {
    let mut classes = Vec::new();
    for path in ["site.css", "../../brand/wordmark.css"] {
        let css = without_comments(&std::fs::read_to_string(site_dir().join(path)).unwrap());
        let mut start = 0;
        for (at, c) in css.char_indices() {
            match c {
                '{' => {
                    let selector = &css[start..at];
                    classes.extend(selector.split('.').skip(1).filter_map(|rest| {
                        let name: String = rest
                            .chars()
                            .take_while(|c| c.is_ascii_alphanumeric() || *c == '-' || *c == '_')
                            .collect();
                        name.starts_with(|c: char| c.is_ascii_alphabetic() || c == '-' || c == '_')
                            .then_some(name)
                    }));
                    start = at + 1;
                }
                '}' | ';' => start = at + 1,
                _ => {}
            }
        }
    }
    classes
}

/// The `data-trunk` links in `index.html`, as `(rel, href)`; a link with
/// no `href` is left out.
fn trunk_links() -> Vec<(String, String)> {
    let html = std::fs::read_to_string(site_dir().join("index.html")).unwrap();
    html.split("<link data-trunk ")
        .skip(1)
        .filter_map(|rest| {
            let tag = &rest[..rest.find('>')?];
            let attr = |name: &str| {
                let start = tag.find(&format!("{name}=\""))? + name.len() + 2;
                Some(tag[start..start + tag[start..].find('"')?].to_string())
            };
            Some((attr("rel")?, attr("href")?))
        })
        .collect()
}

#[test]
fn the_committed_stylesheet_is_current() {
    let path = site_dir().join("utilities.css");
    let generated = stylesheet(&site_class_lists());
    if std::env::var_os("UPDATE_EXPECT").is_some_and(|v| v == "1") {
        std::fs::write(&path, &generated).unwrap();
    }
    let committed = std::fs::read_to_string(&path)
        .unwrap_or_default()
        .replace("\r\n", "\n");
    assert!(
        committed == generated,
        "crates/site/utilities.css is stale: a class was added or removed in src/, or encre-css \
         changed. Regenerate it with UPDATE_EXPECT=1 (see src/style.rs) and read the diff"
    );
}

#[test]
fn every_class_the_site_names_has_a_rule() {
    // encre-css drops a class it does not know without a word (0.21 has no
    // bare `rounded`, and spells `antialiased` as `antialised`), so each
    // class list is checked one class at a time, against the utilities and
    // the hand-written stylesheets.
    let hand_written = hand_written_classes();
    let mut missing: Vec<String> = site_class_lists()
        .iter()
        .flat_map(|list| {
            words(list)
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .filter(|class| !has_rule(class) && !hand_written.contains(class))
        .collect();
    missing.sort();
    missing.dedup();
    assert_eq!(missing, Vec::<String>::new());
}

#[test]
fn every_stylesheet_the_page_links_is_plain_css_in_the_tree() {
    // Trunk downloads a tool for its Tailwind and Sass link types; a
    // `rel="css"` link it only copies.
    let not_plain: Vec<String> = trunk_links()
        .into_iter()
        .filter(|(rel, _)| STYLESHEET_RELS.contains(&rel.as_str()))
        .filter(|(rel, href)| rel != "css" || !site_dir().join(href).is_file())
        .map(|(rel, href)| format!("{rel} {href}"))
        .collect();
    assert_eq!(not_plain, Vec::<String>::new());
}

#[test]
fn the_page_links_the_generated_stylesheet_and_both_hand_written_ones() {
    // `hand_written_classes` reads the two hand-written sheets as though
    // the page loads them.
    let hrefs: Vec<String> = trunk_links()
        .into_iter()
        .filter(|(rel, _)| rel == "css")
        .map(|(_, href)| href)
        .collect();
    let unlinked: Vec<&str> = LINKED_STYLESHEETS
        .into_iter()
        .filter(|sheet| !hrefs.iter().any(|href| href == sheet))
        .collect();
    assert_eq!(unlinked, Vec::<&str>::new(), "linked: {hrefs:?}");
}
